#define main preserved_native_main
#include "../pns-cuda/main.cu"
#undef main
#include <vector>
#include <cstdint>
#include <cstring>
std::vector<char> read(const char*n){FILE*f=fopen(n,"rb");if(!f)exit(3);fseek(f,0,SEEK_END);long nbytes=ftell(f);rewind(f);std::vector<char>a(nbytes);fread(a.data(),1,nbytes,f);fclose(f);return a;}
int main(){constexpr int n=1024,s=312,t=4,seed=5489,Q=2*n*n,W=Q/4+Q;auto mr=read("study_expected_marks_u8.bin"),cr=read("study_expected_conflicts_i32.bin"),rr=read("study_expected_rewards_f64.bin");int*g;float*v;int*m;cudaMalloc(&g,size_t(t)*W*4);cudaMalloc(&v,t*4);cudaMalloc(&m,t*4);auto reset=[&](){cudaMemset(g,0,size_t(t)*W*4);};reset();PetrinetKernel<<<t,256>>>(g,v,m,n,s,seed);if(cudaDeviceSynchronize()!=cudaSuccess)return 4;std::vector<int>state(size_t(t)*W),maxs(t);std::vector<float>vars(t);bool all=true;for(int trial=1;trial<=5;trial++){reset();cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();PetrinetKernel<<<t,256>>>(g,v,m,n,s,seed);auto status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();cudaMemcpy(state.data(),g,state.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(vars.data(),v,t*4,cudaMemcpyDeviceToHost);cudaMemcpy(maxs.data(),m,t*4,cudaMemcpyDeviceToHost);std::vector<float>out={float(n),float(s),float(t),float(seed)};bool ok=status==cudaSuccess;double ma=0;for(int b=0;b<t;b++){auto*bytes=(unsigned char*)(state.data()+size_t(b)*W);uint64_t tokens=0,squares=0;unsigned maximum=0;for(int j=0;j<Q;j++){unsigned a=bytes[j],e=(unsigned char)mr[size_t(b)*Q+j];ok&=a==e;ma=std::max(ma,double(abs(int(a)-int(e))));tokens+=a;squares+=a*a;maximum=std::max(maximum,a);out.push_back(float(a));}ok&=tokens==Q&&maximum==(unsigned)maxs[b];for(int j=0;j<Q;j++){int a=state[size_t(b)*W+Q/4+j],e;memcpy(&e,cr.data()+4*(size_t(b)*Q+j),4);ok&=a==e;ma=std::max(ma,double(abs(a-e)));out.push_back(float(a));}double evar,emax;memcpy(&evar,rr.data()+16*b,8);memcpy(&emax,rr.data()+16*b+8,8);ok&=double(vars[b])==evar&&maxs[b]==emax;ma=std::max(ma,fabs(double(vars[b])-evar));out.push_back(vars[b]);out.push_back(float(maxs[b]));}all&=ok;char name[100];snprintf(name,100,"output_trial%d.bin",trial);FILE*f=fopen(name,"wb");fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",out.size(),ma,ma,name,out.size());}return all?0:1;}
